142	    public Future<BidResponse> holdAuction(AuctionContext context) {
143	        final UidsCookie uidsCookie = context.getUidsCookie();
144	        final BidRequest bidRequest = context.getBidRequest();
145	        final Timeout timeout = context.getTimeout();
146	        final Account account = context.getAccount();
147	
148	        final List<SeatBid> storedResponse = new ArrayList<>();
149	        final BidderAliases aliases = aliases(bidRequest);
150	        final String publisherId = account.getId();
151	        final BidRequestCacheInfo cacheInfo = bidRequestCacheInfo(bidRequest);
152	        final boolean debugEnabled = isDebugEnabled(bidRequest);
153	
154	        return storedResponseProcessor.getStoredResponseResult(bidRequest.getImp(), aliases, timeout)
155	                .map(storedResponseResult -> populateStoredResponse(storedResponseResult, storedResponse))
156	                .compose(impsRequiredRequest -> extractBidderRequests(context, impsRequiredRequest, aliases))
157	                .map(bidderRequests -> updateRequestMetric(
158	                        bidderRequests, uidsCookie, aliases, publisherId, context.getRequestTypeMetric()))
159	                .compose(bidderRequests -> CompositeFuture.join(
160	                        bidderRequests.stream()
161	                                .map(bidderRequest -> requestBids(
162	                                        bidderRequest,
163	                                        auctionTimeout(timeout, cacheInfo.isDoCaching()),
164	                                        debugEnabled,
165	                                        aliases))
166	                                .collect(Collectors.toList())))
167	                // send all the requests to the bidders and gathers results
168	                .map(CompositeFuture::<BidderResponse>list)
169	                .map(bidderResponses -> storedResponseProcessor.mergeWithBidderResponses(
170	                        bidderResponses, storedResponse, bidRequest.getImp()))
171	                .map(bidderResponses -> validateAndAdjustBids(bidderResponses, context, aliases))
172	                .map(bidderResponses -> updateMetricsFromResponses(bidderResponses, publisherId, aliases))
173	                // produce response from bidder results
174	                .compose(bidderResponses -> bidResponseCreator.create(
175	                        bidderResponses,
176	                        context,
177	                        cacheInfo,
178	                        debugEnabled))
179	                .compose(bidResponse -> bidResponsePostProcessor.postProcess(
180	                        context.getRoutingContext(), uidsCookie, bidRequest, bidResponse, account));
181	    }
